#!/usr/bin/env python3
"""Exact private SPI SDK/consumer successor admission. No native qualification."""
import argparse, hashlib, importlib.util, json, os, stat, sys
from pathlib import Path
sys.dont_write_bytecode = True
HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
TYPE = 'EXACT_QUALIFIED_SPI_SDK_CONSUMER_SOURCE141_SUCCESSOR'
AUTHORITY_MEMBERS = frozenset(['adopt_sdk.py', 'binding.json', 'caller-inputs.json', 'current-source-inputs.json', 'historical-inputs.json', 'owning-closure.json', 'predecessor-bytes/.github/workflows/verify.yml', 'predecessor-bytes/Package.swift', 'predecessor-bytes/THIRD_PARTY.yml', 'predecessor-bytes/cli/Sources/MixerBuild/AndroidSDKCompatibility.swift', 'predecessor-bytes/cli/Sources/MixerBuild/Resources/android-build.py', 'predecessor-bytes/cli/Tests/MixerBuildTests/AndroidSDKCompatibilityTests.swift', 'predecessor-bytes/cli/build-tests/current_android_profile.py', 'predecessor-bytes/scripts/ci/check-android-generated-java.py', 'predecessor-bytes/scripts/ci/tests/test_android_generated_java_runner.py', 'predecessor-bytes/sdk/Package.swift', 'predecessor-bytes/sdk/Sources/MixerApple/MixerNativeView.swift', 'predecessor-bytes/sdk/Sources/MixerGuest/GuestUIExchangeV1.swift', 'predecessor-bytes/sdk/Sources/MixerGuest/GuestUIExchangeV2.swift', 'predecessor-bytes/sdk/Sources/MixerUI/Reconciliation.swift', 'predecessor-bytes/verification/plan-continuation-2026-11-07/generated-java-ci-integration/bootstrap.py', 'predecessor-bytes/verification/plan-continuation-2026-11-07/generated-java-ci-integration/test_bootstrap.py', 'predecessor-source-inputs.json', 'root-native-evidence.json', 'test_source141.py', 'workflow-delta.json'])
PREVIOUS = 'verification/native-report-source127-v1'
POLICY = 'cli/Sources/MixerBuild/AndroidSDKCompatibility.swift'
OWNER = 'scripts/ci/check-android-generated-java.py'
MAX_BYTES = 8 * 1024 * 1024

def need(ok, message):
    if not ok:
        raise RuntimeError(message)

def unique(pairs):
    result = {}
    for key, value in pairs:
        need(key not in result, 'Duplicate JSON key: ' + key)
        result[key] = value
    return result

def relative(name):
    need(type(name) is str and name and len(name) <= 1024 and '\\' not in name and '\0' not in name, 'Invalid path')
    p = Path(name)
    need(not p.is_absolute() and p.as_posix() == name and all(x not in ('.', '..', '.git', '__pycache__') for x in p.parts) and name != '.', 'Invalid path')
    return p

def read(path):
    p = Path(path).absolute()
    for ancestor in [*reversed(p.parents), p]:
        need(not ancestor.is_symlink(), 'Symlink forbidden: ' + str(ancestor))
    st = p.stat()
    need(stat.S_ISREG(st.st_mode) and st.st_size <= MAX_BYTES, 'Bounded ordinary file required')
    with p.open('rb') as stream:
        raw = stream.read(MAX_BYTES + 1)
    need(len(raw) <= MAX_BYTES, 'File budget exceeded')
    return raw

def row(raw):
    return {'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()}


ORDINARY_TEST_PATH = 'cli/Tests/MixerBuildTests/GeneratedPublicAndroidV4Tests.swift'
ORDINARY_TEST_PREIMAGE_IDENTITY = {'bytes': 2833, 'sha256': '0c236028b47463103120eb7de0e868017f6938f2cd579e3893cb6e191b3bc701'}
ORDINARY_TEST_PREIMAGE_HEX = ''

SPARSE_HELPER_PATH = 'verification/plan-continuation-2026-11-07/generated-java-ci-integration/test_sparse_checkout.py'
SPARSE_HELPER_PREIMAGE_IDENTITY = {'bytes': 16581, 'sha256': '7f974d1e4dc9c2cf7fc2f6e33b350d5697a365de47255942de5ef0b0384998b0'}
SPARSE_HELPER_PREIMAGE_HEX = ''

SDK_README_PATH = 'sdk/README.md'
SDK_README_PREIMAGE_IDENTITY = {'bytes': 11051, 'sha256': 'c855781aa847142ba369037f5ba9a3fe3df8fed2b8ddfe094bdf8997793b07e4'}
SDK_README_PREIMAGE_HEX = ''

R5090_OWNING_TEST_PREIMAGES = {'cli/build-tests/test_android_staging.py': '', 'cli/build-tests/test_android_sdk_compatibility.py': '', 'cli/build-tests/test_android_public_host.py': ''}
R5090_OWNING_TEST_IDENTITIES = {'cli/build-tests/test_android_staging.py': {'bytes': 6024, 'sha256': 'a2142c1390982fd3a2dc51915db4101c74faeb0c04bf76dc0eaeebf55af61db5'}, 'cli/build-tests/test_android_sdk_compatibility.py': {'bytes': 34200, 'sha256': '53ca38463919c579c3cfc3c996fc3740d2a597639f73b1acc911d8ae1b98ad2c'}, 'cli/build-tests/test_android_public_host.py': {'bytes': 16186, 'sha256': '2ac9c3c502d33f8563aaaf1cf04e98f0682a99ecc4e46493a73c0000a4aeaa6c'}}

def change_preimage(name, change):
    if name in R5090_OWNING_TEST_PREIMAGES:
        need(change['preimage'] == 'adopt_sdk.py' and change['before'] == R5090_OWNING_TEST_IDENTITIES[name], 'Owning Python test predecessor contract differs')
        raw = bytes.fromhex(R5090_OWNING_TEST_PREIMAGES[name])
        need(row(raw) == R5090_OWNING_TEST_IDENTITIES[name], 'Owning Python test predecessor witness differs')
        return raw
    if name == SDK_README_PATH:
        need(change['preimage'] == 'adopt_sdk.py' and change['before'] == SDK_README_PREIMAGE_IDENTITY, 'SDK README predecessor contract differs')
        raw = bytes.fromhex(SDK_README_PREIMAGE_HEX)
        need(row(raw) == SDK_README_PREIMAGE_IDENTITY, 'SDK README predecessor witness differs')
        return raw
    if name == SPARSE_HELPER_PATH:
        need(change['preimage'] == 'adopt_sdk.py' and change['before'] == SPARSE_HELPER_PREIMAGE_IDENTITY, 'Sparse helper predecessor contract differs')
        raw = bytes.fromhex(SPARSE_HELPER_PREIMAGE_HEX)
        need(row(raw) == SPARSE_HELPER_PREIMAGE_IDENTITY, 'Sparse helper predecessor witness differs')
        return raw
    if name == ORDINARY_TEST_PATH:
        need(change['preimage'] == 'adopt_sdk.py' and change['before'] == ORDINARY_TEST_PREIMAGE_IDENTITY, 'Ordinary test predecessor contract differs')
        raw = bytes.fromhex(ORDINARY_TEST_PREIMAGE_HEX)
        need(row(raw) == ORDINARY_TEST_PREIMAGE_IDENTITY, 'Ordinary test predecessor witness differs')
        return raw
    return read(HERE / relative(change['preimage']))

def load(path):
    return json.loads(read(path), object_pairs_hook=unique)

def digest(rows):
    need(type(rows) is dict and len(rows) <= 2048, 'Invalid manifest')
    for name, value in rows.items():
        relative(name)
        need(type(value) is dict and set(value) == {'bytes', 'sha256'} and type(value['bytes']) is int and 0 <= value['bytes'] <= MAX_BYTES and type(value['sha256']) is str and len(value['sha256']) == 64 and all(c in '0123456789abcdef' for c in value['sha256']), 'Invalid identity')
    return hashlib.sha256(''.join(p + '\0' + v['sha256'] + '\n' for p, v in sorted(rows.items())).encode()).hexdigest()

def check_rows(root, rows):
    digest(rows)
    for name, value in rows.items():
        need(row(read(root / relative(name))) == value, 'Owning bytes differ: ' + name)

def closed_members(root, members):
    allowed = set(members)
    for name in allowed:
        relative(name)
    dirs = {p.as_posix() for name in allowed for p in Path(name).parents if p != Path('.')}
    observed, folders = set(), set()
    budget = len(allowed) + len(dirs)
    def walk(directory, prefix=''):
        nonlocal budget
        need(stat.S_ISDIR(directory.lstat().st_mode), 'Ordinary authority directory required')
        with os.scandir(directory) as stream:
            for entry in stream:
                budget -= 1
                need(budget >= 0, 'Authority membership budget exceeded')
                name = prefix + entry.name
                need(name in allowed or name in dirs, 'Extra authority member: ' + name)
                mode = entry.stat(follow_symlinks=False).st_mode
                if name in dirs:
                    need(stat.S_ISDIR(mode), 'Authority directory required')
                    folders.add(name)
                    walk(Path(entry.path), name + '/')
                else:
                    need(stat.S_ISREG(mode), 'Authority file required')
                    observed.add(name)
    walk(root)
    need(observed == allowed and folders == dirs, 'Incomplete authority membership')

def module(name, path):
    read(path)
    spec = importlib.util.spec_from_file_location(name, path)
    result = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(result)
    return result

def inverse(binding, selected):
    t = binding['sdk_transition']
    need(set(t) == {'schema','type','profileBefore','profileAfter','sourceBefore','sourceAfter','sourceCountBefore','sourceCountAfter','changes','qualification','scope'}, 'Transition fields differ')
    need(type(t['schema']) is int and t['schema'] == 1 and t['type'] == TYPE and t['qualification'] is False and t['scope'] == 'private SPI development; native and GA pending', 'Transition type/scope differs')
    need(type(t['sourceCountBefore']) is int and t['sourceCountBefore'] == 127 and type(t['sourceCountAfter']) is int and t['sourceCountAfter'] == 141 and len(selected) == 141 and digest(selected) == t['sourceAfter'], 'Successor source differs')
    previous = dict(selected)
    need(type(t['changes']) is dict and t['changes'], 'Missing source changes')
    for name, change in t['changes'].items():
        relative(name)
        need(set(change) == {'before','after'} and selected.get(name) == change['after'], 'Selected change differs')
        if change['before'] is None:
            del previous[name]
        else:
            previous[name] = change['before']
    need(len(previous) == 127 and digest(previous) == t['sourceBefore'] == '58e548dd97b80f4f023e33efc5a73b857cb7a62018738ac59e1f1b02bcf394f7', 'Source127 inverse differs')
    need(previous == load(HERE / 'predecessor-source-inputs.json') == load(ROOT / PREVIOUS / 'current-source-inputs.json'), 'Exact predecessor map differs')
    old = load(ROOT / PREVIOUS / 'binding.json')
    need(t['profileBefore'] == old['renderer_pair21_transition']['profileAfter'] and t['profileBefore']['id'] == 'mixer.android-source-pair.21', 'Immutable Pair21 differs')
    return previous

def profile_summary(profile):
    result = {'id': profile['id']}
    for kind in ('sdk', 'adapter'):
        result[kind + '_count'] = len(profile[kind + '_files'])
        result[kind + '_sha256'] = digest(profile[kind + '_files'])
        need(result[kind + '_sha256'] == profile[kind + '_compatibility_sha256'], 'Projection digest differs')
    result['java_sources'] = sum(p.endswith('.java') for p in profile['adapter_files'])
    return result

def admit():
    seal = load(HERE / 'seal.json')
    need(type(seal) is dict and set(seal) == {'schema','members','tree_sha256'} and type(seal['members']) is dict and set(seal['members']) == AUTHORITY_MEMBERS, 'Exact authority roster differs')
    need(set(seal) == {'schema','members','tree_sha256'} and type(seal['schema']) is int and seal['schema'] == 1 and digest(seal['members']) == seal['tree_sha256'], 'Seal differs')
    closed_members(HERE, {*seal['members'], 'seal.json'})
    check_rows(HERE, seal['members'])
    b = load(HERE / 'binding.json')
    need(set(b) == {'schema','type','source','profile','sdk_transition','predecessor_authority','predecessor_source127_seal','changes','historical_inputs','owner_paths','root_gates','root_evidence','optional_backend','adoption','activation','aggregate','GA','holdsReleased','limitations'}, 'Binding fields differ')
    need(type(b['schema']) is int and b['schema'] == 1 and b['type'] == TYPE, 'Binding type differs')
    need(b['root_gates'] == {'genuine_actual_native_root':True,'independent_root_review':False,'root_adoption':False} and all(b[k] is False for k in ('adoption','activation','aggregate','GA','holdsReleased')), 'Root gate scope differs')
    need(b['optional_backend'] == {'access':'@_spi(FeatureUIV3)','default_released_API':False,'backend_execution_qualified':False}, 'Optional SPI scope differs')
    evidence = load(HERE / 'root-native-evidence.json')
    need(b['root_evidence'] == {'path':'root-native-evidence.json','identity':row(read(HERE / 'root-native-evidence.json')),'scope':'R4306 actual SPI native PID-event development only'}, 'Native evidence binding differs')
    need(evidence.get('status') == 'PASS_SCOPED_NATIVE_PID_EVENT' and evidence.get('sdkSourceDigest') == '4c3bef98addfc8a58a74e47873f896e738bbe15f781194ef69d51f96b5af869f' and evidence.get('nativePIDEventAcceptance') is True and evidence.get('OS') == 'TERMINAL', 'Root native scope differs')
    ledger = evidence['ledger']
    need(ledger['actualCurrents'] == [0]*14 and ledger['tickets'] == 0 and ledger['invariant'] == 0 and ledger['closeOutcome'] == 'clean' and evidence['guestResult']['staleRejected'] is True and evidence['guestResult']['titleFromNativeControl'] is True, 'Native consuming evidence differs')
    selected = load(HERE / 'current-source-inputs.json')
    need(b['source'] == {'count':141,'sha256':digest(selected),'manifest':'current-source-inputs.json'}, 'Source metadata differs')
    prior = inverse(b, selected)
    need(b['owner_paths'] == {'collector':OWNER,'compiled_profile':POLICY,'current_selector':'cli/build-tests/current_android_profile.py','workflow':'.github/workflows/verify.yml'}, 'Owner contract differs')
    old_members = b['predecessor_authority']
    closed_members(ROOT / PREVIOUS, old_members)
    check_rows(ROOT / PREVIOUS, old_members)
    need(row(read(ROOT / PREVIOUS / 'seal.json')) == b['predecessor_source127_seal'], 'Historical seal changed')
    # The predecessor authority remains raw; inverse bytes, not weakened seals,
    # provide its complete historical view.
    check_rows(ROOT, selected)
    check_rows(ROOT, load(HERE / 'caller-inputs.json'))
    check_rows(ROOT, load(HERE / 'owning-closure.json'))
    owner = module('sdk141_actual_owner', ROOT / OWNER)
    profile = owner.load_profile(ROOT)
    need(profile == b['sdk_transition']['profileAfter'] and profile['id'] == 'mixer.android-source-pair.22' and profile_summary(profile) == b['profile'], 'Current compiled profile differs')
    need(profile['adapter_files'] == b['sdk_transition']['profileBefore']['adapter_files'] and profile['wire'] == b['sdk_transition']['profileBefore']['wire'], 'Unrelated adapter/wire changed')
    need(owner.source_inputs(profile) == selected, 'Actual owning source map differs')
    selector = module('sdk141_current_selector', ROOT / 'cli/build-tests/current_android_profile.py')
    need(selector.BINDING == HERE.relative_to(ROOT) / 'binding.json' and selector.load_current_profile(ROOT) == profile, 'Current selector differs')
    for name, change in b['changes'].items():
        need(set(change) == {'before','after','preimage'} and row(read(ROOT / relative(name))) == change['after'], 'Installed change differs')
        if change['before'] is None:
            need(change['preimage'] is None, 'Null preimage differs')
        else:
            need(row(change_preimage(name, change)) == change['before'], 'Predecessor byte identity differs')
    history = load(HERE / 'historical-inputs.json')
    need(b['historical_inputs'] == {'count':len(history),'sha256':digest(history)}, 'Historical inputs metadata differs')
    need(set(prior) <= set(history), 'Incomplete historical source inventory')
    for name, expected in history.items():
        c = b['changes'].get(name)
        raw = change_preimage(name, c) if c and c['before'] is not None else read(ROOT / relative(name))
        need(row(raw) == expected, 'Historical input differs: ' + name)
    return b, selected, prior

def verify(installed=False):
    b, selected, prior = admit()
    return {'schema':1,'type':TYPE,'source_count':len(selected),'source_sha256':digest(selected),'predecessor_source_count':len(prior),'predecessor_source_sha256':digest(prior),'profile':b['profile'],'historical_native_only':True,'root_gates':b['root_gates'],'adoption':False,'activation':False,'aggregate':False,'GA':False,'holdsReleased':False}

def prepare_predecessor(out):
    b, selected, prior = admit()
    out = Path(out).absolute()
    need(not out.exists() and not out.is_symlink(), 'Fresh historical tree required')
    for p in out.parents:
        need(not p.is_symlink(), 'Historical output symlink')
    values = {}
    for name in load(HERE / 'historical-inputs.json'):
        c = b['changes'].get(name)
        values[name] = change_preimage(name, c) if c and c['before'] is not None else read(ROOT / relative(name))
    need(sum(map(len, values.values())) <= 64 * 1024 * 1024, 'Historical copy budget')
    out.mkdir(parents=True, mode=0o700)
    for name, raw in values.items():
        p = out / relative(name)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(raw)
    return {'source127':digest(prior),'files':len(values),'out':str(out),'native_gate':False}

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    p = sub.add_parser('verify'); p.add_argument('--workflow-installed', action='store_true')
    p = sub.add_parser('prepare-predecessor'); p.add_argument('--out', type=Path, required=True)
    a = parser.parse_args()
    print(json.dumps(verify(a.workflow_installed) if a.command == 'verify' else prepare_predecessor(a.out), sort_keys=True))
    return 0
if __name__ == '__main__':
    sys.exit(main())
